-- 싸이월드 세대 용어 2개 추가 (id 563-564) — 운영자 아침 검수 승인 2026-09-22, outdated-slang.
-- draft_payload 그대로 승격. pronunciation은 draft에 없어 표기 그대로([도토리], [파도타기]).
-- 도토리: 표준어 '도토리'(열매)와 표제어가 같다 — short_desc에 싸이월드를 앞세워 구분.
-- 파도타기: 이름 유래의 1차 출처가 없어 origin에 단정하지 않음. 체육관 응원 파도타기와 구분은 usage에.
-- related_words의 미니홈피·일촌·싸이월드·눈팅은 아직 words에 없음(일촌은 후보 대기 중).
--
-- NOTE: filename timestamp differs from the production migration version
-- (MCP apply time becomes the version) — repo-wide convention, see CLAUDE.md.

begin;

insert into public.words (id, word, romanization, category, secondary_category, short_desc, short_desc_i18n, pronunciation, meanings, origin, origin_i18n, usage, usage_i18n, related_words, likes, saves, translations) values
('563', '도토리', 'Do-to-ri', 'outdated-slang', NULL, '싸이월드 미니홈피를 꾸미던 100원짜리 사이버머니', '{"de": "Die 100-Won-Cyberwährung, die jede Cyworld-Minihompy schmückte", "en": "The 100-won cyber currency that decorated every Cyworld minihompy", "es": "La moneda virtual de 100 wones que decoraba cada minihompy de Cyworld", "ja": "サイワールドのミニホムピを飾った100ウォンのサイバーマネー", "vi": "Đồng tiền ảo 100 won từng trang hoàng mọi minihompy Cyworld"}'::jsonb, '[도토리]', '[{"type": "명사", "examples": [{"de": "Meine Eicheln sind alle — schickst du mir eine?", "es": "Me quedé sin bellotas, ¿me mandas una?", "ja": "ドトリ切れちゃった、1個だけ送って。", "vi": "Tớ hết hạt dẻ rồi, gửi cho một hạt đi.", "eng": "I am out of acorns — send me just one?", "kor": "나 도토리 떨어졌어, 한 개만 보내 줘."}, {"de": "Weißt du noch, als wir Hintergrundmusik mit Eicheln gekauft haben?", "es": "¿Te acuerdas de cuando comprábamos música de fondo con bellotas?", "ja": "ドトリでBGM買ってた頃覚えてる?", "vi": "Còn nhớ hồi mua nhạc nền bằng hạt dẻ không?", "eng": "Remember when we bought background music with acorns?", "kor": "도토리로 배경음악 사던 시절 기억나?"}], "definition": "2000년대 국민 SNS였던 싸이월드 안에서만 통하던 사이버머니. 1개에 100원이며 휴대폰 소액결제나 문화상품권으로 충전했다. 미니홈피 배경 스킨, 다이어리 스티커, 미니미 옷, 흘러나오는 배경음악까지 전부 도토리가 있어야 살 수 있었다. 친구 홈피에 도토리를 보내 주는 것이 곧 애정 표현이기도 했다.", "definition_i18n": {"de": "Die Binnenwährung von Cyworld, Koreas nationalem SNS der 2000er. Eine Eichel kostete 100 Won, aufgeladen per Handy-Kleinbetrag oder Gutschein. Skins, Tagebuch-Sticker, Kleidung für den Minimi-Avatar und die Hintergrundmusik der Seite ließen sich nur damit kaufen — und einem Freund Eicheln zu schicken war selbst schon eine Zuneigungsgeste.", "en": "The in-app currency of Cyworld, Korea''s national SNS of the 2000s. One acorn cost 100 won, topped up by phone micropayment or gift vouchers. Skins, diary stickers, outfits for your minimi avatar and the background music on your page all had to be bought with them — and sending acorns to a friend''s page was itself a way of showing you cared.", "es": "La moneda interna de Cyworld, la red social nacional de Corea en los 2000. Cada bellota costaba 100 wones y se recargaba por micropago móvil o vales. Fondos de pantalla, pegatinas del diario, ropa para tu avatar minimi y la música de tu página se compraban con ellas, y regalar bellotas a la página de un amigo era en sí una muestra de cariño.", "ja": "2000年代の国民的SNSサイワールド内だけで通用したサイバーマネー。1個100ウォンで、携帯少額決済や図書文化商品券でチャージした。ミニホムピの背景スキン、ダイアリーのステッカー、ミニミの服、流れるBGMまですべてドトリがないと買えなかった。友達のホムピにドトリを送ることが愛情表現でもあった。", "vi": "Tiền ảo nội bộ của Cyworld, mạng xã hội quốc dân Hàn Quốc thập niên 2000. Mỗi hạt dẻ giá 100 won, nạp bằng thanh toán vi mô qua điện thoại hoặc phiếu quà tặng. Giao diện trang, sticker nhật ký, quần áo cho avatar minimi và cả nhạc nền đều phải mua bằng nó — và tặng hạt dẻ cho trang của bạn bè chính là cách thể hiện tình cảm."}}]'::jsonb, '기존 사이버머니들의 딱딱하고 상업적인 이미지를 피해 친근한 이름을 붙인 것으로 보인다는 게 정설이다. 전성기에는 도토리 판매만으로 하루 매출 3억 원을 기록했고, 경제 전문지가 ''도토리 경제''라는 말을 쓸 만큼 하나의 현상이었다. 싸이월드가 저물면서 말도 함께 쓰이지 않게 됐다. 열매를 뜻하는 표준어 ''도토리''와 글자가 같아 지금 이 말을 사이버머니 뜻으로 알아듣는 사람은 당시를 겪은 세대뿐이다.', '{"de": "Gängig gilt der Name als bewusste Abkehr von der kühlen, kommerziellen Anmutung früherer Cyberwährungen hin zu etwas Heimeligem. Auf dem Höhepunkt brachte allein der Eichelverkauf 300 Millionen Won pro Tag, und Wirtschaftsmagazine schrieben von der ''Eichel-Ökonomie''. Mit Cyworld verschwand auch das Wort. Da es identisch mit dem gewöhnlichen Wort für die Eichel geschrieben wird, hört heute nur die damalige Generation die Währungsbedeutung heraus.", "en": "The name is generally explained as a deliberate move away from the cold, commercial feel of earlier cyber currencies toward something homely. At its peak, acorn sales alone brought in 300 million won a day, and business magazines wrote about the ''acorn economy''. As Cyworld faded, so did the word. Since it is spelled identically to the ordinary Korean word for an oak acorn, only the generation that lived through it hears the currency meaning today.", "es": "Se explica como un alejamiento deliberado de la imagen fría y comercial de otras monedas virtuales hacia algo entrañable. En su apogeo, solo la venta de bellotas generaba 300 millones de wones al día, y las revistas económicas hablaban de la ''economía de la bellota''. Al apagarse Cyworld, se apagó la palabra. Como se escribe igual que la bellota de roble, hoy solo quienes vivieron esa época oyen el sentido monetario.", "ja": "従来のサイバーマネーの硬く商業的なイメージを避け、親しみやすい名前を付けたものというのが通説。全盛期にはドトリ販売だけで1日3億ウォンの売上を記録し、経済誌が「ドトリ経済」と書くほどの現象だった。サイワールドの衰退とともに語も使われなくなった。木の実を指す標準語「도토리」と表記が同じため、今この語をサイバーマネーの意味で聞き取れるのは当時を生きた世代だけ。", "vi": "Cách giải thích phổ biến là họ cố tình tránh hình ảnh lạnh lùng, thương mại của các loại tiền ảo trước đó để chọn một cái tên thân thuộc. Thời hoàng kim, riêng bán hạt dẻ đã đem về 300 triệu won mỗi ngày, và báo kinh tế còn viết về ''nền kinh tế hạt dẻ''. Cyworld tàn thì từ này cũng tàn. Vì viết y hệt từ chỉ quả sồi, ngày nay chỉ thế hệ từng trải mới nghe ra nghĩa tiền ảo."}'::jsonb, '''도토리 보내다'', ''도토리 충전하다'', ''도토리 떨어졌다''처럼 썼다. 지금 이 말을 꺼내면 싸이월드 세대의 향수를 건드리는 셈이다. 표준어로는 참나무 열매를 뜻하므로 문맥이 없으면 그쪽으로 알아듣는다.', '{"de": "In festen Wendungen: Eicheln schicken, Eicheln aufladen, keine Eicheln mehr haben. Heute erwähnt, trifft es direkt die Nostalgie der Cyworld-Generation. Ohne Kontext versteht man das gewöhnliche Wort für die Eichel.", "en": "Used in set phrases: 도토리 보내다 (send acorns), 도토리 충전하다 (top up), 도토리 떨어졌다 (out of acorns). Bringing it up now is a direct hit of Cyworld-generation nostalgia. Without context, listeners will hear the ordinary word for an oak acorn.", "es": "Se usaba en frases hechas: mandar bellotas, recargar bellotas, quedarse sin bellotas. Sacarlo hoy es nostalgia pura de la generación Cyworld. Sin contexto, se entiende como la bellota del roble.", "ja": "「ドトリを送る」「ドトリをチャージする」「ドトリが切れた」のように使った。今この語を出せばサイワールド世代の郷愁を直撃する。文脈がなければ標準語のどんぐり(木の実)と受け取られる。", "vi": "Dùng trong các cụm cố định: gửi hạt dẻ, nạp hạt dẻ, hết hạt dẻ. Nhắc tới bây giờ là chạm thẳng vào nỗi hoài niệm của thế hệ Cyworld. Không có ngữ cảnh thì người nghe sẽ hiểu là quả sồi."}'::jsonb, '{미니홈피,일촌,싸이월드}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Cyworld''s acorn cyber-currency"}, {"lang": "🇯🇵 JA", "text": "サイワールドのサイバーマネー「ドトリ」"}, {"lang": "🇨🇳 ZH", "text": "Cyworld 的虚拟货币「橡子」"}, {"lang": "🇻🇳 VI", "text": "Tiền ảo ''hạt dẻ'' của Cyworld"}, {"lang": "🇪🇸 ES", "text": "La bellota, moneda virtual de Cyworld"}, {"lang": "🇩🇪 DE", "text": "Cyworlds Eichel-Cyberwährung"}]'::jsonb),
('564', '파도타기', 'Pa-do-ta-gi', 'outdated-slang', NULL, '싸이월드에서 남의 홈피를 끝없이 타고 다니던 일', '{"de": "Endloses Springen zwischen Cyworld-Freundesseiten", "en": "Endlessly hopping between Cyworld friend pages", "es": "Saltar sin fin entre páginas de amigos en Cyworld", "ja": "サイワールドで他人のホムピを次々巡ること", "vi": "Nhảy hết trang bạn này sang trang bạn khác trên Cyworld"}'::jsonb, '[파도타기]', '[{"type": "명사", "examples": [{"de": "Ich bin von Seite zu Seite gesprungen und plötzlich war es drei Uhr morgens.", "es": "Me puse a saltar de página en página y de repente eran las tres de la mañana.", "ja": "파도타기してたら朝の3時になってた。", "vi": "Lướt hết trang này sang trang khác, ngoảnh lại đã ba giờ sáng.", "eng": "I started page-hopping and suddenly it was three in the morning.", "kor": "파도타기 하다가 새벽 세 시 됐어."}], "definition": "싸이월드 미니홈피에서 내 일촌의 일촌으로, 다시 그 사람의 일촌으로 타고 넘어가며 남의 홈피를 계속 구경하던 기능이자 그 행동. 한번 시작하면 몇 시간이 사라진다는 점에서 지금의 유튜브·틱톡 무한 스크롤과 성격이 같다.", "definition_i18n": {"de": "Die Cyworld-Funktion — und Angewohnheit —, von der Seite eines Freundes zu dessen Freund zu springen und immer weiter, stundenlang fremde Minihompys zu durchstöbern. Im Kern dieselbe Falle wie heutiges Endlos-Scrollen.", "en": "The Cyworld feature — and the habit — of jumping from your friend page to their friend page and onward, browsing strangers minihompys for hours. Structurally it is the same trap as today infinite scroll on YouTube or TikTok.", "es": "La función de Cyworld — y la costumbre — de saltar de la página de un amigo a la de su amigo, y así sin parar, curioseando minihompys ajenos durante horas. En el fondo es la misma trampa que el scroll infinito de hoy.", "ja": "サイワールドのミニホムピで、自分の일촌からその일촌へと次々飛び移って他人のホムピを見続ける機能であり、その行為。始めると数時間消えるという点で、今のYouTubeやTikTokの無限スクロールと同じ性質を持つ。", "vi": "Tính năng Cyworld — và cũng là thói quen — nhảy từ trang bạn mình sang trang bạn của bạn, cứ thế xem minihompy người lạ hàng giờ. Về bản chất giống hệt cái bẫy lướt vô tận của YouTube hay TikTok bây giờ."}}]'::jsonb, '싸이월드 미니홈피의 기능 이름으로, 파도를 타듯 일촌에서 일촌으로 옮겨 다닌다는 데서 온 이름으로 설명된다. 다만 작명 경위를 밝힌 공식 기록은 확인되지 않는다. 2000년대 한 시대를 풍미한 대표 기능으로 꼽히며, 도토리·일촌평과 함께 언론이 싸이월드를 회고할 때마다 빠지지 않고 등장한다.', '{"de": "Der Name einer Cyworld-Minihompy-Funktion, meist erklärt als Von-Freund-zu-Freund-Surfen wie auf Wellen — eine offizielle Quelle zur Namensgebung fand sich allerdings nicht. Sie gilt als prägende Funktion der 2000er und fehlt in keinem Cyworld-Rückblick neben 도토리 und 일촌평.", "en": "The name of a Cyworld minihompy feature, generally explained as riding from friend to friend the way a surfer rides waves — though no official account of the naming has been found. It is remembered as one of the defining functions of the 2000s and shows up in every press retrospective on Cyworld alongside 도토리 and 일촌평.", "es": "Nombre de una función del minihompy de Cyworld, explicada normalmente como ir de amigo en amigo igual que se surfean olas, aunque no consta el origen oficial del nombre. Se recuerda como una de las funciones que definieron los 2000 y aparece en todo reportaje nostálgico sobre Cyworld junto a 도토리 y 일촌평.", "ja": "サイワールドのミニホムピ機能名で、波に乗るように일촌から일촌へ移っていくことに由来すると説明される。ただし命名経緯の公式記録は確認できない。2000年代を象徴する機能として記憶され、도토리・일촌평とともにサイワールド回顧記事に必ず登場する。", "vi": "Tên một tính năng của minihompy Cyworld, thường được giải thích là lướt từ bạn này sang bạn khác như lướt sóng, dù chưa tìm thấy ghi chép chính thức về cách đặt tên. Nó được nhớ như một trong những tính năng tiêu biểu của thập niên 2000, luôn xuất hiện trong các bài báo hoài niệm về Cyworld cùng 도토리 và 일촌평."}'::jsonb, '싸이월드와 함께 사라진 말이라 지금은 추억을 이야기할 때만 쓴다. 같은 행동을 요즘은 그냥 「스크롤 지옥」이나 「눈팅」으로 표현한다. 체육관 응원의 파도타기와는 다른 뜻이니 문맥으로 구별해야 한다.', '{"de": "Es verschwand mit Cyworld und kommt heute nur in Nostalgiegesprächen vor; dasselbe Verhalten heißt jetzt 스크롤 지옥 oder 눈팅. Achtung: Es hat nichts mit der La-Ola-Welle im Stadion zu tun, die genauso heißt — am Kontext unterscheiden.", "en": "It vanished with Cyworld and now appears only in nostalgia talk; the same behaviour is described today as 스크롤 지옥 (scroll hell) or 눈팅. Note it is unrelated to the stadium crowd wave, which uses the same word — tell them apart by context.", "es": "Desapareció con Cyworld y hoy solo sale en charlas nostálgicas; esa conducta ahora se describe como 스크롤 지옥 o 눈팅. Ojo: no tiene que ver con la ola del público en un estadio, que usa la misma palabra — distíngelas por contexto.", "ja": "サイワールドとともに消え、今は思い出話でしか使わない。同じ行動は今「스크롤 지옥」や「눈팅」と表現する。同じ語のスタジアムのウェーブとは別の意味なので文脈で見分ける必要がある。", "vi": "Nó biến mất cùng Cyworld, nay chỉ dùng khi ôn chuyện cũ; hành vi đó giờ được gọi là 스크롤 지옥 hay 눈팅. Lưu ý từ này khác với sóng cổ vũ trên sân vận động tuy viết giống nhau — phải dựa vào ngữ cảnh."}'::jsonb, '{일촌,눈팅,도토리}'::text[], 0, 0, '[{"lang": "🇺🇸 EN", "text": "Cyworld page-hopping"}, {"lang": "🇯🇵 JA", "text": "ホムピ巡り"}, {"lang": "🇨🇳 ZH", "text": "一路点进好友主页闲逛"}, {"lang": "🇻🇳 VI", "text": "Lướt hết trang bạn này sang bạn khác"}, {"lang": "🇪🇸 ES", "text": "Saltar de perfil en perfil"}, {"lang": "🇩🇪 DE", "text": "Von Profil zu Profil surfen"}]'::jsonb);

commit;
